from lib import build
R=[]
R.append((7860482,
("Carne molida de pavo con champiñones","Carne molida salteada rápida en una salsa espesa y sabrosa.","6","214 g",
 ["1 cucharadita de aceite de girasol","3 cebollas, finamente picadas","3 zanahorias, cortadas en cubitos finos","500 g de carne molida de muslo de pavo","250 g de champiñones, en rebanadas","1 tallo de apio, cortado en cubitos finos","1 cucharada colmada de harina común","1 cubo de caldo de pollo bajo en sal disuelto en 500 ml de agua hirviendo","una buena pizca de pimienta blanca","2 cucharaditas de salsa de soya reducida en sal"],
 ["Caliente el aceite en una olla. Agregue las cebollas y las zanahorias y cocine de 4 a 5 minutos, hasta que las cebollas empiecen a dorarse.","Agregue la carne molida de pavo, los champiñones y el apio. Cocine de 4 a 5 minutos, deshaciendo los grumos de carne con una cuchara de madera.","Espolvoree la harina y mezcle bien para que todo quede cubierto. Vierta poco a poco el caldo, revolviendo continuamente, hasta que comience a espesar.","Agregue la pimienta y la salsa de soya, revuelva y baje el fuego a bajo. Tape y cocine a fuego lento durante 3 a 4 minutos."],
 ["Ideal para servir con verduras de hoja verde y camotes al horno.","Funciona bien con carne molida de cerdo, res o cordero.","Para una versión vegana, use una alternativa vegana en lugar de la carne molida y un cubo de caldo de verduras.","Para convertirlo en una tarta baja en grasa, ponga la carne molida en un molde para tarta y cubra con 4 hojas de masa filo ligeramente barnizadas con 2 cucharaditas de aceite de canola; hornee de 7 a 10 minutos.","Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente bien hasta que esté bien caliente por completo.","@FV"],[]),
("لحم الديك الرومي المفروم مع الفطر","لحم مفروم سريع التحضير بنكهة مالحة في مرق غني.","6","214 جم",
 ["1 ملعقة صغيرة من زيت عباد الشمس","3 حبات بصل، مفرومة ناعمًا","3 حبات جزر، مقطعة مكعبات صغيرة","500 جم من لحم فخذ الديك الرومي المفروم","250 جم من الفطر، مقطع إلى شرائح","1 ساق كرفس، مقطعة مكعبات صغيرة","1 ملعقة كبيرة مكتنزة من الدقيق العادي","1 مكعب مرق دجاج قليل الملح مذاب في 500 مل من الماء المغلي","رشة وافرة من الفلفل الأبيض","2 ملعقة صغيرة من صلصة الصويا قليلة الملح"],
 ["سخّن الزيت في قدر. أضف البصل والجزر واطهها لمدة 4-5 دقائق حتى يبدأ البصل بالاحمرار.","أضف لحم الديك الرومي المفروم والفطر والكرفس. اطهها لمدة 4-5 دقائق مع تفتيت أي كتل من اللحم المفروم بملعقة خشبية.","انثر الدقيق وقلّب جيدًا ليتغطى كل شيء. اسكب المرق تدريجيًا مع التحريك المستمر حتى يبدأ بالتكاثف.","أضف الفلفل وصلصة الصويا وقلّب وخفّف الحرارة إلى أدنى درجة. غطِّه واتركه على نار هادئة لمدة 3-4 دقائق."],
 ["يُقدَّم بشكل مثالي مع الخضراوات الورقية الخضراء والبطاطا الحلوة المشوية.","تناسب هذه الوصفة لحم الخنزير أو البقر أو الضأن المفروم.","للحصول على نسخة نباتية صرفة، استخدم بديلًا نباتيًا بدلًا من اللحم المفروم ومكعب مرق خضار.","لتحويله إلى فطيرة قليلة الدسم، ضع اللحم المفروم في طبق فطائر وغطِّه بـ 4 طبقات من عجينة الفيلو مدهونة برفق بـ 2 ملعقة صغيرة من زيت الكانولا واخبزها لمدة 7-10 دقائق.","تعليمات التجميد: يمكن تجميده بعد الطهي. اتركه ليذوب في الثلاجة أو الميكروويف وأعد تسخينه جيدًا حتى يصبح ساخنًا تمامًا.","@FV"],[])))
R.append((7863056,
("Bolitas de atún con salsa de tomate","Crujientes bolitas de atún en salsa de tomate, ideales para la cena con los niños. Enviada por Eiri Stephen","2","380 g",
 ["un puñado grande (unos 25 g) de hierbas frescas mixtas (por ejemplo, perejil, menta, orégano, tomillo y albahaca)","1 lata de 160 g de atún en aceite de girasol; escurra el aceite y resérvelo","25 g de piñones","45 g de pan molido integral","ralladura de 1 limón","una pizca de sal y pimienta","1 huevo, batido","200 g de puré de tomate (passata)","2 rodajas de limón, para servir"],
 ["Pique finamente las hierbas, luego mezcle todos los ingredientes y forme 12 bolitas del tamaño de una nuez.","Ponga el aceite de la lata de atún en una sartén y dore las bolitas de atún durante 10 a 12 minutos, volteándolas con regularidad.","Mientras tanto, caliente el puré de tomate, agregue las bolitas de atún y sirva con una rodaja de limón."],
 ["Si no tiene hierbas frescas, use 2 cucharaditas de hierbas mixtas secas.","Podría agregar una pizca de hojuelas de chile o un diente de ajo machacado para darles un toque picante.","El tamaño de las porciones para niños variará según su edad y necesidades nutricionales. La información nutricional se basa en el tamaño de una porción para adultos.","@FV"],[]),
("كرات التونة بصلصة الطماطم","كرات تونة صغيرة مقرمشة في صلصة الطماطم، مثالية لوجبة العشاء مع الأطفال. أرسلتها Eiri Stephen","2","380 جم",
 ["حفنة كبيرة (نحو 25 جم) من الأعشاب الطازجة المشكّلة (مثل البقدونس والنعناع والأوريجانو والزعتر والريحان)","1 علبة (160 جم) من التونة في زيت عباد الشمس، صفِّ الزيت واحتفظ به","25 جم من الصنوبر","45 جم من فتات الخبز البني","قشر ليمونة واحدة","رشة من الملح والفلفل","1 بيضة، مخفوقة","200 جم من صلصة الطماطم المصفّاة (باساتا)","2 شريحة ليمون للتقديم"],
 ["افرم الأعشاب ناعمًا، ثم اخلط جميع المكونات معًا وشكّلها على هيئة 12 كرة بحجم حبة الجوز.","ضع الزيت الذي في علبة التونة في مقلاة وحمّر كرات التونة لمدة 10-12 دقيقة مع تقليبها بانتظام.","في هذه الأثناء، سخّن صلصة الطماطم المصفّاة، وأضف كرات التونة وقدّمها مع شريحة ليمون."],
 ["إذا لم تتوفر لديك أعشاب طازجة، فاستخدم 2 ملعقة صغيرة من الأعشاب المجففة المشكّلة.","يمكنك إضافة رشة من رقائق الفلفل الحار أو فص ثوم مهروس لإضفاء بعض الحدّة عليها.","تختلف أحجام الحصص للأطفال بحسب أعمارهم واحتياجاتهم الغذائية. تعتمد المعلومات الغذائية على حجم حصة شخص بالغ.","@FV"],[])))
R.append((7868675,
("Wraps vegetarianos de brunch","Este platillo rápido y sabroso satisfará sus antojos de brunch.","2","204 g",
 ["1 pulverización de aceite de girasol","4 huevos, batidos","1 cucharada de picado fresco","cebollín","75 g de queso suave ligero","2 champiñones portobello o de campo grandes","2 cucharaditas de vinagre balsámico","2 tomates ciruela, sin semillas y cortados en cubitos finos","¼ de cebolla morada, en rodajas muy finas"],
 ["Caliente una sartén pequeña y rocíe 2 pulverizaciones de aceite. Agregue ¼ del huevo batido e incline la sartén para que el huevo se extienda formando un círculo de 15 cm. Cocine durante 30 segundos, voltee con cuidado y cocine otros 30 segundos. Pase a un plato y repita para obtener 4 wraps en total.","Mezcle el cebollín con el queso. Ponga los champiñones en un plato, rocíe cada uno con 1 cucharadita de vinagre, cubra con film plástico, perfore y cocine en el microondas a máxima potencia durante 2 minutos. Corte en rebanadas finas.","Unte los wraps con el queso, acomode encima los champiñones, esparza los tomates picados y la cebolla, enrolle sin apretar y sirva. Delicioso caliente o frío."],
 ["@FV"],[]),
("لفائف برانش النباتية","هذا الطبق السريع واللذيذ سيلبي رغبتك في وجبة البرانش.","2","204 جم",
 ["1 بخة من زيت عباد الشمس","4 بيضات، مخفوقة","1 ملعقة كبيرة من المفروم الطازج","ثوم معمر","75 جم من الجبن الطري الخفيف","2 حبة فطر بورتوبيللو أو فطر حقلي كبيرة","2 ملعقة صغيرة من خل البلسميك","2 حبة طماطم برقوقية، منزوعة البذور ومقطعة مكعبات صغيرة","¼ حبة بصل أحمر، مقطعة إلى شرائح رفيعة جدًا"],
 ["سخّن مقلاة صغيرة وارشّها بـ 2 ضغطة من الزيت. أضف ¼ كمية البيض المخفوق وحرّك المقلاة بحيث يتوزع البيض ويكوّن دائرة قطرها 15 سم. اطهه لمدة 30 ثانية، ثم اقلبه بحذر واطهه 30 ثانية أخرى. انقله إلى طبق وكرر العملية للحصول على 4 لفائف في المجموع.","اخلط الثوم المعمر مع الجبن. ضع الفطر على طبق، ورشّ على كل حبة 1 ملعقة صغيرة من الخل، وغطِّه بورق التغليف البلاستيكي، واثقبه وضعه في الميكروويف على أعلى قدرة لمدة 2 دقيقة. قطّعه إلى شرائح رفيعة.","ادهن اللفائف بالجبن ورتّب الفطر فوقها، وانثر الطماطم المفرومة والبصل، ثم لفّها لفًا غير محكم وقدّمها. لذيذة ساخنة أو باردة."],
 ["@FV"],[])))
R.append((7870024,
("Pollo estilo casero griego","Este platillo tradicional griego es delicioso servido con ensalada o verduras.","4","378 g",
 ["4 pechugas de pollo deshuesadas y sin piel (150 g cada una)","500 g de papas, sin pelar y cortadas en gajos","ralladura y jugo de 2 limones","1 cucharada de aceite de oliva","200 ml de caldo de pollo","4 dientes de ajo, pelados","2 cucharadas de perejil fresco, picado","pimienta negra recién molida"],
 ["Precaliente el horno a 200 ºC (marca de gas 6).","Coloque el pollo en una fuente para horno y acomode las papas alrededor.","Mezcle todos los demás ingredientes, excepto el perejil, y vierta sobre el pollo.","Cubra con papel aluminio y hornee durante 35 minutos; retire el papel aluminio y cocine otros 15 a 20 minutos.","Espolvoree el perejil, sazone al gusto y sirva."],
 ["Esta receta también funciona bien con cortes magros de carne como filete de cordero o lomo de cerdo.","Podría usar camotes en lugar de papas comunes.","Podría hacer esta receta más saludable usando caldo de pollo reducido en sal.","Sirva con ensalada o verduras de temporada para ayudar a alcanzar sus 5 porciones diarias de frutas y verduras.","Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador y recaliente hasta que esté bien caliente por completo.","@FV"],[]),
("دجاج على الطريقة اليونانية المنزلية","هذا الطبق اليوناني التقليدي لذيذ عند تقديمه مع السلطة أو الخضار.","4","378 جم",
 ["4 صدور دجاج بدون عظم ولا جلد (150 جم لكل صدر)","500 جم من البطاطس، غير مقشّرة ومقطعة إلى أسافين","قشر مبشور وعصير 2 ليمونة","1 ملعقة كبيرة من زيت الزيتون","200 مل من مرق الدجاج","4 فصوص ثوم، مقشّرة","2 ملعقة كبيرة من البقدونس الطازج، مفروم","فلفل أسود مطحون طازجًا"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (درجة الغاز 6).","ضع الدجاج في وعاء يصلح للفرن ورتّب البطاطس حوله.","اخلط جميع المكونات المتبقية، ما عدا البقدونس، واسكبها فوق الدجاج.","غطِّه بورق الألمنيوم واخبزه لمدة 35 دقيقة، ثم أزل الورق واتركه ينضج 15-20 دقيقة أخرى.","انثر البقدونس وتبّل حسب الذوق وقدّمه."],
 ["تناسب هذه الوصفة أيضًا قطع اللحم قليلة الدسم مثل فيليه الضأن أو فيليه لحم الخنزير.","يمكنك استخدام البطاطا الحلوة بدلًا من البطاطس العادية.","يمكنك جعل هذه الوصفة أكثر صحة باستخدام مرق دجاج قليل الملح.","قدّمه مع السلطة أو الخضار الموسمية لتساعدك على بلوغ حصصك الـ 5 يوميًا من الفاكهة والخضار.","تعليمات التجميد: يمكن تجميده بعد الطهي. اتركه ليذوب في الثلاجة وأعد تسخينه حتى يصبح ساخنًا تمامًا.","@FV"],[])))
R.append((7878991,
("Brochetas de pollo marinado con cuscús","Este platillo de pollo combina muy bien con un cuscús al limón.","2","489 g",
 ["1 pechuga de pollo grande (200 g), cortada en tiras","4 cucharadas de suero de leche (buttermilk)","1 cucharadita de pesto","1 diente de ajo, machacado","1 pimiento rojo, cortado en trozos","2 champiñones grandes, en rebanadas gruesas","150 g de cuscús","200 ml de caldo de pollo hirviendo","ralladura y jugo de 1 limón","1 bolsa de 80 g de hojas de rúcula","2 cebollines, en rodajas"],
 ["Ponga el pollo, el suero de leche, el pesto y el ajo en un tazón y revuelva bien para integrar. Remoje las brochetas de madera en agua durante 15 minutos para evitar que se quemen.","Deje marinar durante 20 minutos. Ensarte el pollo en las brochetas alternando con el pimiento y los champiñones.","Colóquelas bajo un grill caliente y áselas de 6 a 7 minutos, volteándolas de vez en cuando.","Mientras tanto, ponga el cuscús en un tazón, vierta el caldo y la ralladura y el jugo de limón. Cubra el tazón con film plástico y deje reposar durante 5 minutos.","Incorpore las hojas de rúcula y los cebollines y sirva con las brochetas de pollo."],
 ["Para una versión aún más saludable, pruebe a servirlo con cuscús integral.","Es excelente servido frío y es un buen almuerzo para llevar.","Para una versión con pescado, use cubos de salmón o camarones extra grandes.","@FV"],[]),
("أسياخ الدجاج المتبّلة مع الكسكس","يتناسب طبق الدجاج هذا بشكل رائع مع كسكس بنكهة الليمون.","2","489 جم",
 ["1 صدر دجاج كبير (200 جم)، مقطع إلى شرائح","4 ملاعق كبيرة من اللبن الرائب (بترميلك)","1 ملعقة صغيرة من البيستو","1 فص ثوم، مهروس","1 حبة فلفل رومي أحمر، مقطعة قطعًا","2 حبة فطر كبيرة، مقطعة إلى شرائح سميكة","150 جم من الكسكس","200 مل من مرق الدجاج المغلي","قشر مبشور وعصير 1 ليمونة","1 كيس (80 جم) من أوراق الجرجير","2 حبة بصل أخضر، مقطعة إلى شرائح"],
 ["ضع الدجاج واللبن الرائب والبيستو والثوم في وعاء وقلّب جيدًا لتمتزج المكونات. انقع الأسياخ الخشبية في الماء لمدة 15 دقيقة لمنعها من الاحتراق.","اتركه ليتتبّل لمدة 20 دقيقة. اغرس الدجاج في الأسياخ بالتناوب مع الفلفل الرومي والفطر.","ضعها تحت شواية ساخنة واشوِها لمدة 6-7 دقائق مع تقليبها من حين لآخر.","في هذه الأثناء، ضع الكسكس في وعاء، واسكب فوقه المرق وقشر الليمون وعصيره. غطِّ الوعاء بورق التغليف البلاستيكي واتركه لمدة 5 دقائق.","قلّب أوراق الجرجير والبصل الأخضر مع الكسكس وقدّمه مع أسياخ الدجاج."],
 ["للحصول على نسخة أكثر صحة، جرّب تقديمه مع كسكس القمح الكامل.","يُقدَّم بشكل رائع باردًا ويصلح وجبة غداء ممتازة للحمل.","للحصول على نسخة بالسمك، استخدم مكعبات السلمون أو الجمبري الكبير جدًا.","@FV"],[])))
R.append((7879167,
("Gratinado de berenjena y calabacín con parmesano","Una versión saludable de un clásico gratinado italiano.","4","448 g",
 ["2 berenjenas grandes (unos 700 g), cortadas en discos de 1 cm","2 calabacines grandes, cortados en tiras de 0.5 cm","1 cucharada de aceite de oliva","1 cebolla, finamente picada","1 pimiento rojo, finamente picado","2 a 3 dientes de ajo, machacados","1 cucharadita colmada de orégano seco","1 lata de 400 g de tomates picados","50 g de queso parmesano, finamente rallado","120 g de mozzarella reducida en grasa, en rebanadas finas"],
 ["Precaliente el horno a 180 °C (marca de gas 4). Ase al grill las berenjenas y los calabacines hasta que se doren ligeramente por ambos lados.","Mientras tanto, ponga el aceite en una olla con la cebolla, revolviendo de vez en cuando durante 5 minutos. Luego, agregue el pimiento rojo, revolviendo con regularidad otros 5 minutos.","Incorpore el ajo, el orégano y los tomates, y cocine a fuego lento durante 5 minutos.","Ponga un poco de la salsa en una fuente para horno, cubra con rebanadas de berenjena y calabacín, luego agregue más salsa y espolvoree con queso parmesano. Repita hasta llegar a la última capa de berenjena y calabacín; después cubra con la salsa restante, el parmesano y, por último, las rebanadas de mozzarella.","Hornee de 30 a 40 minutos, hasta que esté dorado.","Sirva con una molida de pimienta negra, ensalada, pasta sin gluten o polenta para que el platillo siga siendo libre de gluten."],
 ["Para una alternativa vegetariana al parmesano, cámbielo por un queso duro de tipo vegetariano.","Puede armar este platillo, refrigerarlo y hornearlo más tarde, o al día siguiente. Incluso puede congelarlo y cocinarlo cuando lo necesite.","Puede cambiar el queso parmesano por Grana Padano, que es un poco más económico y sabe igual de bien.","Instrucciones para congelar: Se puede congelar una vez cocinado. Divida en porciones para congelar. Descongele en el microondas y luego recaliente en el microondas o cubierto con papel aluminio en un horno moderado. Recaliente hasta que esté bien caliente por completo.","@FV"],[]),
("باذنجان وكوسا بالبارميزان في الفرن","نسخة صحية من طبق إيطالي كلاسيكي يُخبز في الفرن.","4","448 جم",
 ["2 حبة باذنجان كبيرة (نحو 700 جم)، مقطعة إلى أقراص بسمك 1 سم","2 حبة كوسا كبيرة، مقطعة إلى شرائح بسمك 0.5 سم","1 ملعقة كبيرة من زيت الزيتون","1 حبة بصل، مفرومة ناعمًا","1 حبة فلفل رومي أحمر، مفرومة ناعمًا","2-3 فصوص ثوم، مهروسة","1 ملعقة صغيرة مكتنزة من الأوريجانو المجفف","1 علبة (400 جم) من الطماطم المقطعة","50 جم من جبن البارميزان، مبشور ناعمًا","120 جم من جبن الموزاريلا قليل الدسم، مقطع إلى شرائح رفيعة"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4). اشوِ الباذنجان والكوسا على الشواية حتى يحمرّا قليلًا من كل جانب.","في هذه الأثناء، ضع الزيت في قدر مع البصل مع التحريك من حين لآخر لمدة 5 دقائق. بعد ذلك، أضف الفلفل الرومي الأحمر مع التحريك بانتظام لمدة 5 دقائق أخرى.","أضف الثوم والأوريجانو والطماطم، واتركها على نار هادئة لمدة 5 دقائق.","ضع جزءًا من الصلصة في وعاء يصلح للفرن، وضع فوقها شرائح الباذنجان والكوسا، ثم أضف مزيدًا من الصلصة وانثر جبن البارميزان. كرر ذلك حتى الطبقة الأخيرة من الباذنجان والكوسا، ثم غطِّها بالصلصة المتبقية والبارميزان، وأخيرًا شرائح الموزاريلا.","اخبزها في الفرن لمدة 30-40 دقيقة حتى تصبح بنية ذهبية.","قدّمها مع رشة من الفلفل الأسود والسلطة أو المعكرونة الخالية من الغلوتين أو البولينتا للحفاظ على الطبق خاليًا من الغلوتين."],
 ["للحصول على بديل نباتي للبارميزان، استبدله بجبن صلب مناسب للنباتيين.","يمكنك تجهيز هذا الطبق ووضعه في الثلاجة وخبزه لاحقًا – أو في اليوم التالي. بل يمكنك تجميده وطهيه عند الحاجة.","يمكنك استبدال جبن البارميزان بجبن غرانا بادانو، وهو أرخص قليلًا وطعمه جيد بالقدر نفسه.","تعليمات التجميد: يمكن تجميده بعد الطهي. قسّمه إلى حصص للتجميد. اتركه ليذوب في الميكروويف، ثم أعد تسخينه في الميكروويف أو مغطى بورق الألمنيوم في فرن متوسط الحرارة. أعد تسخينه حتى يصبح ساخنًا تمامًا.","@FV"],[])))
R.append((7882491,
("Paté de frijoles blancos (butter beans)","Un apetitoso dip de frijoles blancos con cebollín, pepino y menta, servido con crujientes bastones de verduras.","4","209 g",
 ["1 lata de 400 g de frijoles blancos (butter beans), escurridos (240 g)","4 cebollines, finamente picados (50 g)","6 cm de pepino, cortado en cubitos muy finos (80 g)","2 cucharadas de yogur natural sin azúcar","1 diente de ajo, machacado","1 cucharada de aceite de oliva extra virgen","jugo y ralladura de ½ limón","3 ramitas de menta fresca, picadas","una buena pizca de pimienta","una pizca de pimentón","4 tomates cherry","1 tallo de apio, cortado en bastones","½ bulbo de hinojo, cortado en bastones","1 zanahoria grande, cortada en bastones","1 pimiento amarillo, cortado en bastones","crudités mixtas"],
 ["Triture bien la mitad de los frijoles con un tenedor hasta que quede bastante suave. Triture ligeramente la otra mitad y luego mezcle ambas.","Incorpore los cebollines, el pepino, el yogur, el ajo, el aceite de oliva, el limón, la menta y la pimienta, y reserve.","Mientras tanto, prepare los bastones de verduras para mojar.","Mezcle de nuevo el paté, espolvoree con pimentón y sirva."],
 ["Funciona bien con frijoles cannellini o alubias blancas. Para una versión vegana, use una alternativa de yogur sin lácteos.","Dele un toque picante con una cucharadita de pasta de curry. Puede usar cualquier verdura para mojar: elija una variedad de colores para que sea más atractivo.","Instrucciones para congelar: el dip se puede congelar. Descongele en el refrigerador y consuma de inmediato.","La información nutricional anterior incluye la sugerencia de presentación con crudités.","@FV"],[]),
("باتيه الفاصولياء البيضاء الكبيرة","غموس شهي من الفاصولياء البيضاء الكبيرة مع البصل الأخضر والخيار والنعناع، يُقدَّم مع أعواد الخضار المقرمشة.","4","209 جم",
 ["1 علبة (400 جم) من الفاصولياء البيضاء الكبيرة، مصفّاة (240 جم)","4 حبات بصل أخضر، مفرومة ناعمًا (50 جم)","6 سم من الخيار، مقطع مكعبات صغيرة جدًا (80 جم)","2 ملعقة كبيرة من الزبادي الطبيعي غير المحلّى","1 فص ثوم، مهروس","1 ملعقة كبيرة من زيت الزيتون البكر الممتاز","عصير وقشر ½ ليمونة","3 أغصان نعناع طازج، مفرومة","رشة وافرة من الفلفل","رشة بابريكا","4 حبات طماطم كرزية","1 ساق كرفس، مقطعة أعوادًا","½ بصلة شمر، مقطعة أعوادًا","1 حبة جزر كبيرة، مقطعة أعوادًا","1 حبة فلفل رومي أصفر، مقطعة أعوادًا","خضار نيئة مشكّلة"],
 ["اهرس نصف الفاصولياء جيدًا بالشوكة حتى تصبح ناعمة إلى حد كبير. اهرس النصف الآخر هرسًا خفيفًا، ثم اخلطهما معًا.","أضف البصل الأخضر والخيار والزبادي والثوم وزيت الزيتون والليمون والنعناع والفلفل واخلطها، ثم ضعها جانبًا.","في هذه الأثناء، حضّر أعواد الخضار للغمس.","اخلط الباتيه مرة أخرى، وانثر البابريكا فوقه وقدّمه."],
 ["تناسب هذه الوصفة فاصولياء كانيليني أو الفاصولياء البيضاء الصغيرة. للحصول على نسخة نباتية صرفة، استخدم بديل زبادي غير لبني.","أضف إليه حدّة بملعقة صغيرة من معجون الكاري. يمكنك استخدام أي خضار للغمس – اختر مجموعة متنوعة من الألوان لتبقى الوجبة مشوّقة.","تعليمات التجميد: الغموس صالح للتجميد. اتركه ليذوب في الثلاجة واستخدمه فورًا.","تشمل القيم الغذائية المذكورة أعلاه اقتراح التقديم مع الخضار النيئة المقطعة.","@FV"],[])))
R.append((7882956,
("Hamburguesa de pavo","La carne molida magra de pechuga de pavo y un pan integral relleno de ensalada hacen de esta la hamburguesa más saludable de la ciudad.","8","258 g",
 ["1 rebanada de pan integral","1 huevo, batido","500 g de carne molida de pechuga de pavo","1 cebolla, rallada finamente","2 zanahorias, ralladas finamente","4 a 6 dientes de ajo, machacados","una pizca de pimienta negra","8 bollos integrales, abiertos por la mitad (unos 60 g cada uno)","150 g de lechuga","4 tomates, en rodajas finas","1 cebolla, en rodajas finas"],
 ["En un tazón, desmenuce el pan y agréguelo al huevo batido. Reserve, pero mezcle de vez en cuando, hasta que el pan haya absorbido todo el huevo.","Agregue la carne molida de pavo, la cebolla, la zanahoria, el ajo y la pimienta al huevo con el pan y mezcle bien.","Forme 8 hamburguesas (de unos 8 cm de diámetro y 2½ cm de grosor), colóquelas en un plato o charola, cubra con film plástico y refrigere por al menos 20 minutos, aunque es mejor una o dos horas.","Ase las hamburguesas al grill de 6 a 8 minutos por cada lado, asegurándose de que queden bien cocidas.","Tueste los bollos, si lo desea, y arme sus hamburguesas con la lechuga, el tomate y la cebolla."],
 ["Dé un toque picante a sus hamburguesas con una pizca de hojuelas de chile o 1 cucharadita de comino molido. O agregue hierbas como tomillo o romero.","Para un toque festivo, agregue 1 cucharada de arándanos rojos secos a la mezcla de las hamburguesas.","Instrucciones para congelar: Se pueden congelar crudas o cocidas. Congele en porciones envueltas individualmente con papel encerado entre cada hamburguesa. Descongele por completo en el refrigerador o en el microondas y caliente bien hasta que estén bien calientes y cocidas por completo.","@FV"],[]),
("برغر الديك الرومي","لحم صدر الديك الرومي المفروم الخالي من الدهن وخبز القمح الكامل المحشو بالسلطة يجعلان منه أكثر البرغر صحة في المدينة!","8","258 جم",
 ["1 شريحة خبز قمح كامل","1 بيضة، مخفوقة","500 جم من لحم صدر الديك الرومي المفروم","1 حبة بصل، مبشورة ناعمًا","2 حبة جزر، مبشورة ناعمًا","4-6 فصوص ثوم، مهروسة","رشة من الفلفل الأسود","8 أرغفة صغيرة من القمح الكامل، مشقوقة (نحو 60 جم لكل رغيف)","150 جم من الخس","4 حبات طماطم، مقطعة إلى شرائح رفيعة","1 حبة بصل، مقطعة إلى شرائح رفيعة"],
 ["في وعاء، فتّت الخبز وأضفه إلى البيض المخفوق. ضعه جانبًا مع تقليبه من حين لآخر حتى يمتص الخبز كل البيض.","أضف لحم الديك الرومي المفروم والبصل والجزر والثوم والفلفل إلى البيض والخبز واخلط جيدًا.","شكّل 8 أقراص برغر (بقطر نحو 8 سم وسمك 2½ سم) وضعها على طبق أو صينية، وغطِّها بورق التغليف البلاستيكي وضعها في الثلاجة لمدة 20 دقيقة على الأقل، ويفضل ساعة أو ساعتان.","اشوِ أقراص البرغر لمدة 6-8 دقائق على كل جانب مع التأكد من نضجها تمامًا.","حمّص الخبز، إن رغبت، وكوّن البرغر مع الخس والطماطم والبصل."],
 ["أضف حدّة إلى البرغر برشة من رقائق الفلفل الحار أو 1 ملعقة صغيرة من الكمون المطحون. أو أضف أعشابًا مثل الزعتر أو إكليل الجبل.","للحصول على نكهة احتفالية، أضف 1 ملعقة كبيرة من التوت البري المجفف إلى خليط البرغر.","تعليمات التجميد: يمكن تجميده نيئًا أو مطهوًا. جمّده في حصص ملفوفة بشكل فردي مع وضع ورق زبدة بين كل قرص وآخر. اتركه ليذوب تمامًا في الثلاجة أو الميكروويف وسخّنه جيدًا حتى يصبح ساخنًا تمامًا ومطهوًا بالكامل.","@FV"],[])))
R.append((7886286,
("Desayuno vegetariano al horno","Este sustancioso desayuno vegetariano le dará energía para el día. Es rápido y fácil de preparar y está lleno de verduras.","2","368 g",
 ["4 pulverizaciones de aceite en aerosol de 1 kcal","2 champiñones portobello grandes, sin tallos (80 g cada uno)","50 g de garbanzos enlatados, escurridos","½ cucharadita de pimentón ahumado","1 bolsa de 200 g de espinacas baby lavadas","2 cucharadas de queso suave bajo en grasa con hierbas","1 tomate bola pequeño (130 g)","1 cucharadita de vinagre balsámico","1 aguacate pequeño (140 g, peso ya preparado)"],
 ["Precaliente el horno a 200 °C (marca de gas 6). Rocíe la bandeja para hornear y los champiñones con un par de pulverizaciones del aceite en aerosol de 1 kcal. Coloque los champiñones parados en el centro. Mezcle los garbanzos con el pimentón y espárzalos sobre la bandeja. Cocine durante 5 minutos.","Corte la esquina de la bolsa de espinacas y cocine en el microondas a máxima potencia durante 2 minutos. Agite y cocine 1 minuto más, hasta que se marchiten. Deje enfriar y luego exprima el jugo de las espinacas por la esquina cortada. Vierta las espinacas en un tazón e incorpore el queso suave. Sazone con pimienta negra.","Coloque una rodaja de tomate encima de cada champiñón, rocíe con balsámico y cubra con las espinacas.","Corte el aguacate en rebanadas, colóquelas en cruz sobre las espinacas y rocíe ligeramente con aceite en aerosol.","Cocine de 12 a 15 minutos, hasta que el aguacate se ablande. Divida entre los platos para servir. Esparza los garbanzos por encima y sirva con un chorrito adicional de balsámico."],
 ["@FV"],[]),
("فطور الخضار المخبوز","هذا الفطور النباتي المشبع سيمنحك الطاقة ليومك. سريع وسهل التحضير ومليء بالخضار.","2","368 جم",
 ["4 بخات من بخاخ زيت 1 سعرة حرارية","2 حبة فطر بورتوبيللو كبيرة، بعد إزالة السيقان (80 جم لكل حبة)","50 جم من الحمص المعلب، مصفّى","½ ملعقة صغيرة من البابريكا المدخّنة","1 كيس (200 جم) من السبانخ الصغيرة المغسولة","2 ملعقة كبيرة من الجبن الطري قليل الدسم بالأعشاب","1 حبة طماطم لحمية صغيرة (130 جم)","1 ملعقة صغيرة من خل البلسميك","1 حبة أفوكادو صغيرة (140 جم، وزنها بعد التحضير)"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (درجة الغاز 6). رشّ صينية الخبز والفطر بضغطتين من بخاخ الزيت 1 سعرة حرارية. ضع الفطر واقفًا في الوسط. قلّب الحمص مع البابريكا وانثره على صينية الخبز. اتركه ينضج لمدة 5 دقائق.","اقطع زاوية كيس السبانخ وضعه في الميكروويف على أعلى قدرة لمدة 2 دقيقة. حرّكه واتركه 1 دقيقة أخرى حتى تذبل السبانخ. اتركها لتبرد، ثم اعصر عصارة السبانخ من الزاوية المقطوعة. ضع السبانخ في وعاء وقلّب فيها الجبن الطري. تبّل بالفلفل الأسود.","ضع شريحة طماطم فوق كل حبة فطر، ورشّ عليها البلسميك، ثم غطِّها بالسبانخ.","قطّع الأفوكادو إلى شرائح، ورتّبها بشكل متقاطع فوق السبانخ، ثم رشّها برفق ببخاخ الزيت.","اتركها تنضج لمدة 12-15 دقيقة حتى يلين الأفوكادو. وزّعها على أطباق التقديم. انثر الحمص فوقها وقدّمها مع رشة إضافية من البلسميك."],
 ["@FV"],[])))
R.append((7887932,
("Pimientos baby rellenos","Estos canapés coloridos y saludables son ideales para una fiesta de Navidad.","20","35 g",
 ["50 g de quinoa","1 diente de ajo, machacado","10 g de pasas, picadas toscamente","1 cucharadita de comino molido","1 cebollín, finamente picado","1 cucharada de puré de tomate","jugo de ½ limón","1 cucharadita de aceite","10 pimientos baby mixtos","5 tomates cherry, cortados en cuartos","75 g de mozzarella reducida en grasa, cortada en 10 trozos","1 cucharadita de cebollín picado, para decorar","una buena molida de pimienta negra"],
 ["Precaliente el horno a 180 °C (marca de gas 4).","Enjuague la quinoa en un colador, luego póngala en una olla con 150 ml de agua. Lleve a ebullición, baje el fuego y cocine a fuego lento durante 15 minutos. Escurra el agua que no se haya absorbido y esponje con un tenedor.","Ponga la quinoa en un tazón con el ajo, las pasas, el comino, el cebollín, el puré de tomate y el jugo de limón. Mezcle bien y reserve.","Mientras tanto, engrase ligeramente una bandeja para hornear y corte los pimientos por la mitad a lo largo, dejando los rabillos y quitando las semillas.","Divida la quinoa en partes iguales entre los pimientos y cubra cada uno con un cuarto de tomate y un trozo pequeño de mozzarella.","Coloque los pimientos en una bandeja para hornear y hornee de 10 a 12 minutos, hasta que los pimientos se hayan ablandado y el queso se haya derretido. Espolvoree con el cebollín y una molida de pimienta negra."],
 ["Puede armarlos el día anterior y dejarlos en el refrigerador toda la noche, y luego hornearlos justo antes de necesitarlos.","Podría agregar otras especias, como curry en polvo, o usar cuscús en lugar de quinoa.","Instrucciones para congelar: Congele en porciones y luego descongele en el microondas. Caliente hasta que estén bien calientes, revolviendo con regularidad. Consuma de inmediato y deseche las sobras.","@FV"],[]),
("فلفل صغير محشو","هذه المقبلات الملونة والصحية رائعة لحفلة عيد الميلاد.","20","35 جم",
 ["50 جم من الكينوا","1 فص ثوم، مهروس","10 جم من الزبيب، مفروم فرمًا خشنًا","1 ملعقة صغيرة من الكمون المطحون","1 حبة بصل أخضر، مفرومة ناعمًا","1 ملعقة كبيرة من معجون الطماطم","عصير ½ ليمونة","1 ملعقة صغيرة من الزيت","10 حبات فلفل رومي صغير مشكّل","5 حبات طماطم كرزية، مقطعة أرباعًا","75 جم من جبن الموزاريلا قليل الدسم، مقطع إلى 10 قطع","1 ملعقة صغيرة من الثوم المعمر المفروم للتزيين","رشة وافرة من الفلفل الأسود المطحون"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4).","اشطف الكينوا في مصفاة، ثم ضعها في قدر مع 150 مل من الماء. اتركها حتى تغلي، ثم خفّف الحرارة واتركها على نار هادئة لمدة 15 دقيقة. صفِّ الماء الذي لم تمتصه وفكّكها بالشوكة.","ضع الكينوا في وعاء مع الثوم والزبيب والكمون والبصل الأخضر ومعجون الطماطم وعصير الليمون. اخلط جيدًا وضعه جانبًا.","في هذه الأثناء، ادهن صينية خبز بقليل من الزيت وقطّع حبات الفلفل إلى نصفين طوليًا مع ترك العُنُق في مكانه وإزالة البذور.","وزّع الكينوا بالتساوي على حبات الفلفل وضع على كل منها ربع حبة طماطم وقطعة صغيرة من الموزاريلا.","ضع الفلفل في صينية الخبز واخبزه لمدة 10-12 دقيقة حتى يلين الفلفل ويذوب الجبن. انثر الثوم المعمر ورشة من الفلفل الأسود المطحون."],
 ["يمكنك تجهيزها في اليوم السابق وتركها في الثلاجة طوال الليل ثم خبزها قبل الحاجة إليها مباشرة.","يمكنك إضافة توابل أخرى، مثل مسحوق الكاري، أو استخدام الكسكس بدلًا من الكينوا.","تعليمات التجميد: جمّدها في حصص ثم اتركها لتذوب في الميكروويف. سخّنها حتى تصبح ساخنة تمامًا مع التحريك بانتظام. تناولها فورًا وتخلّص من أي بقايا.","@FV"],[])))
R.append((7890431,
("Verduras de hoja con chile y ajo","¡Rápido, fácil y chisporroteante! Este acompañamiento pasa de la sartén al plato en solo 20 minutos. Esta receta fue seleccionada en colaboración con Slimming World.","4","228 g",
 ["Aceite en aerosol para cocinar bajo en calorías","3 dientes de ajo, en rodajas finas","2 chiles rojos, sin semillas y picados toscamente","1 cebolla morada, en rodajas finas","2 pimientos verdes, sin semillas y picados toscamente","200 g de brócoli de tallo largo, recortado","150 g de col rizada (kale), picada toscamente","Jugo de 1 limón sin encerar"],
 ["Rocíe una sartén grande antiadherente con un par de pulverizaciones de aceite en aerosol para cocinar bajo en calorías y colóquela a fuego medio-alto. Agregue el ajo y los chiles y fría durante 1 minuto. Agregue la cebolla, los pimientos y el brócoli con 100 ml de agua y fría de 2 a 3 minutos. Incorpore la col rizada y fría durante 2 minutos. Sazone ligeramente con pimienta negra, agregue un chorrito de jugo de limón y sirva."],
 ["@FV"],[]),
("خضار ورقية بالفلفل الحار والثوم","سريع وسهل ومحمّر! يكون طبق الخضار الجانبي هذا جاهزًا من المقلاة إلى الطبق في 20 دقيقة فقط. تم اختيار هذه الوصفة بالشراكة مع Slimming World.","4","228 جم",
 ["بخاخ طهي قليل السعرات الحرارية","3 فصوص ثوم، مقطعة إلى شرائح رفيعة","2 حبة فلفل حار أحمر، منزوعة البذور ومفرومة فرمًا خشنًا","1 حبة بصل أحمر، مقطعة إلى شرائح رفيعة","2 حبة فلفل رومي أخضر، منزوعة البذور ومفرومة فرمًا خشنًا","200 جم من البروكلي طويل الساق، مقصوص","150 جم من اللفت الأجعد (كيل)، مفروم فرمًا خشنًا","عصير 1 ليمونة غير مشمّعة"],
 ["رشّ مقلاة كبيرة غير لاصقة بضغطتين من بخاخ الطهي قليل السعرات الحرارية وضعها على نار متوسطة إلى عالية. أضف الثوم والفلفل الحار وقلّبهما لمدة 1 دقيقة. أضف البصل والفلفل الرومي والبروكلي مع 100 مل من الماء وقلّبها لمدة 2-3 دقائق. أضف اللفت الأجعد وقلّبه لمدة 2 دقيقة. تبّل برفق بالفلفل الأسود، وأضف عصرة من عصير الليمون وقدّمه."],
 ["@FV"],[])))
R.append((7891265,
("Salmón con costra de ajonjolí y ensalada de ejotes","Un platillo sencillo que está listo en menos de 30 minutos.","2","372 g",
 ["jugo de ½ limón","2 cucharaditas de aceite de ajonjolí tostado","2 cucharaditas de cinco especias chino","2 filetes de salmón (unos 120 g cada uno)","1 cucharada de semillas de ajonjolí","1 cucharadita de aceite de girasol","200 g de ejotes finos, recortados","2 tomates, picados","½ cebolla morada pequeña, finamente picada","1 lechuga little gem, finamente cortada en tiras","2 cucharaditas de vinagre balsámico"],
 ["Precaliente el horno a 180 °C (marca de gas 4). Mezcle bien en un tazón el jugo de limón, el aceite de ajonjolí y las cinco especias chino, y cubra por completo los filetes de salmón.","Coloque los filetes de salmón en un plato y espolvoree con las semillas de ajonjolí. Una vez bien cubiertos, ponga el salmón en una bandeja para hornear ligeramente engrasada con 1 cucharadita de aceite de girasol. Espolvoree las semillas restantes sobre el pescado y hornee de 12 a 15 minutos.","Mientras tanto, hierva los ejotes durante 3 a 4 minutos y luego sumérjalos en agua fría para enfriarlos.","Mezcle los ejotes, los tomates, la cebolla y la lechuga, y divida entre dos platos. Desmenuce el salmón encima y rocíe con el vinagre balsámico."],
 ["Esta receta también funciona bien con filetes de caballa o filetes de atún fresco.","Cuando sea temporada, se pueden usar espárragos en lugar de ejotes.","Sumergir los ejotes finos en agua fría detiene el proceso de cocción.","@FV"],[]),
("سلمون بقشرة السمسم وسلطة الفاصولياء الخضراء","طبق بسيط يكون جاهزًا في أقل من 30 دقيقة.","2","372 جم",
 ["عصير ½ ليمونة","2 ملعقة صغيرة من زيت السمسم المحمص","2 ملعقة صغيرة من مسحوق التوابل الخمسة الصيني","2 شريحة سلمون (نحو 120 جم لكل شريحة)","1 ملعقة كبيرة من بذور السمسم","1 ملعقة صغيرة من زيت عباد الشمس","200 جم من الفاصولياء الخضراء الرفيعة، مقصوصة","2 حبة طماطم، مفرومة","½ حبة بصل أحمر صغيرة، مفرومة ناعمًا","1 رأس خس ليتل جيم، مقطع شرائح رفيعة","2 ملعقة صغيرة من خل البلسميك"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4). اخلط عصير الليمون وزيت السمسم ومسحوق التوابل الخمسة الصيني في وعاء جيدًا، ثم غطِّ شرائح السلمون به تمامًا.","ضع شرائح السلمون في طبق وانثر عليها بذور السمسم. بعد أن تتغطى جيدًا، ضع السلمون على صينية خبز مدهونة برفق بـ 1 ملعقة صغيرة من زيت عباد الشمس. انثر ما تبقى من البذور فوق السمك واخبزه في الفرن لمدة 12-15 دقيقة.","في هذه الأثناء، اسلق الفاصولياء لمدة 3-4 دقائق، ثم اغمرها في ماء بارد لتبرد.","اخلط الفاصولياء والطماطم والبصل والخس معًا ووزّعها على طبقين. فتّت السلمون فوقها ورشّ عليها خل البلسميك."],
 ["تناسب هذه الوصفة أيضًا فيليه الماكريل أو شرائح التونة الطازجة.","عند توفر الموسم، يمكن استخدام الهليون بدلًا من الفاصولياء الخضراء.","غمر الفاصولياء الخضراء الرفيعة في ماء بارد يوقف عملية الطهي.","@FV"],[])))
